import{_ as A,H as e,f as B,i as t}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"第六封信-副作用比药效更值得让人留心","description":"","frontmatter":{},"headers":[],"relativePath":"去无方向的信/第六封信-副作用比药效更值得让人留心.md","filePath":"去无方向的信/第六封信-副作用比药效更值得让人留心.md","lastUpdated":1795542896000}'),s={name:"去无方向的信/第六封信-副作用比药效更值得让人留心.md"};function i(n,E,a,p,F,o){return e(),B("div",null,[...E[0]||(E[0]=[t('<h1 id="第六封信-副作用比药效更值得让人留心" tabindex="-1">第六封信-副作用比药效更值得让人留心 <a class="header-anchor" href="#第六封信-副作用比药效更值得让人留心" aria-label="Permalink to &quot;第六封信-副作用比药效更值得让人留心&quot;">​</a></h1><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%2585%25AD%25E5%25B0%2581%25E4%25BF%25A1-%25E5%2589%25AF%25E4%25BD%259C%25E7%2594%25A8%25E6%25AF%2594%25E8%258D%25AF%25E6%2595%2588%25E6%259B%25B4%25E5%2580%25BC%25E5%25BE%2597%25E8%25AE%25A9%25E4%25BA%25BA%25E7%2595%2599%25E5%25BF%2583/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%2585%25AD%25E5%25B0%2581%25E4%25BF%25A1-%25E5%2589%25AF%25E4%25BD%259C%25E7%2594%25A8%25E6%25AF%2594%25E8%258D%25AF%25E6%2595%2588%25E6%259B%25B4%25E5%2580%25BC%25E5%25BE%2597%25E8%25AE%25A9%25E4%25BA%25BA%25E7%2595%2599%25E5%25BF%2583/1.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%2585%25AD%25E5%25B0%2581%25E4%25BF%25A1-%25E5%2589%25AF%25E4%25BD%259C%25E7%2594%25A8%25E6%25AF%2594%25E8%258D%25AF%25E6%2595%2588%25E6%259B%25B4%25E5%2580%25BC%25E5%25BE%2597%25E8%25AE%25A9%25E4%25BA%25BA%25E7%2595%2599%25E5%25BF%2583/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%2585%25AD%25E5%25B0%2581%25E4%25BF%25A1-%25E5%2589%25AF%25E4%25BD%259C%25E7%2594%25A8%25E6%25AF%2594%25E8%258D%25AF%25E6%2595%2588%25E6%259B%25B4%25E5%2580%25BC%25E5%25BE%2597%25E8%25AE%25A9%25E4%25BA%25BA%25E7%2595%2599%25E5%25BF%2583/2.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%2585%25AD%25E5%25B0%2581%25E4%25BF%25A1-%25E5%2589%25AF%25E4%25BD%259C%25E7%2594%25A8%25E6%25AF%2594%25E8%258D%25AF%25E6%2595%2588%25E6%259B%25B4%25E5%2580%25BC%25E5%25BE%2597%25E8%25AE%25A9%25E4%25BA%25BA%25E7%2595%2599%25E5%25BF%2583/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%2585%25AD%25E5%25B0%2581%25E4%25BF%25A1-%25E5%2589%25AF%25E4%25BD%259C%25E7%2594%25A8%25E6%25AF%2594%25E8%258D%25AF%25E6%2595%2588%25E6%259B%25B4%25E5%2580%25BC%25E5%25BE%2597%25E8%25AE%25A9%25E4%25BA%25BA%25E7%2595%2599%25E5%25BF%2583/3.png" alt=""></a></p><p>生生：</p><p>你好哇。</p><p>这次还是要围绕着光圈、快门和 ISO 说来说去。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%2585%25AD%25E5%25B0%2581%25E4%25BF%25A1-%25E5%2589%25AF%25E4%25BD%259C%25E7%2594%25A8%25E6%25AF%2594%25E8%258D%25AF%25E6%2595%2588%25E6%259B%25B4%25E5%2580%25BC%25E5%25BE%2597%25E8%25AE%25A9%25E4%25BA%25BA%25E7%2595%2599%25E5%25BF%2583/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%2585%25AD%25E5%25B0%2581%25E4%25BF%25A1-%25E5%2589%25AF%25E4%25BD%259C%25E7%2594%25A8%25E6%25AF%2594%25E8%258D%25AF%25E6%2595%2588%25E6%259B%25B4%25E5%2580%25BC%25E5%25BE%2597%25E8%25AE%25A9%25E4%25BA%25BA%25E7%2595%2599%25E5%25BF%2583/4.png" alt=""></a></p><ul><li>注意，这张表格已经和第三封信里的表格不太一样了</li></ul><p>你现在已经知道，光圈六选一，快门六选一，ISO 六选一，然后就出来了一张照片儿，而问题是，怎么选？我已经问过好多遍了，怎么选？</p><p>你现在已经知道“不同的曝光参数组合可以拍出曝光一致的照片儿”了，所以，为什么我们还要那么事儿事儿地特定住某一档光圈，特定住某一档快门，特定住某一档 ISO 呢？</p><p>因为，这三个参数的共同点是都可以影响曝光，但他们除了都能影响曝光之外，还各有各的“副作用”。</p><p>药效肯定都是好事，但副作用偶尔能死人。</p><p>首先，光圈：</p><p>我们知道，如果快门和 ISO 不变，光圈越大，相机里的进光量就越多，照片也就会越亮，反之亦然。</p><p>但我们现在还应该知道，光圈越大，景深越浅，也就是我们常说的“虚化越强”，而光圈越小，景深越深。景深如果足够深，甚至可以做到让一张照片儿从前到后一览无余，一点虚化都没有。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%2585%25AD%25E5%25B0%2581%25E4%25BF%25A1-%25E5%2589%25AF%25E4%25BD%259C%25E7%2594%25A8%25E6%25AF%2594%25E8%258D%25AF%25E6%2595%2588%25E6%259B%25B4%25E5%2580%25BC%25E5%25BE%2597%25E8%25AE%25A9%25E4%25BA%25BA%25E7%2595%2599%25E5%25BF%2583/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%2585%25AD%25E5%25B0%2581%25E4%25BF%25A1-%25E5%2589%25AF%25E4%25BD%259C%25E7%2594%25A8%25E6%25AF%2594%25E8%258D%25AF%25E6%2595%2588%25E6%259B%25B4%25E5%2580%25BC%25E5%25BE%2597%25E8%25AE%25A9%25E4%25BA%25BA%25E7%2595%2599%25E5%25BF%2583/5.png" alt=""></a></p><p>再来，快门：</p><p>我们知道，如果光圈和 ISO 不变，快门越慢，感光元件的受光时间就越长，照片也就会越亮，反之亦然。</p><p>但我们现在还应该知道，快门越快，越能够定格住一个瞬间，尤其是抓拍一些动态的画面，可以尽可能地不糊片儿，而快门越慢，越容易糊掉。但这当然也不是说快就好，慢就不好，而是快和慢各有各的好，因为有的时候，很可能我们就是需要让一些东西糊掉。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%2585%25AD%25E5%25B0%2581%25E4%25BF%25A1-%25E5%2589%25AF%25E4%25BD%259C%25E7%2594%25A8%25E6%25AF%2594%25E8%258D%25AF%25E6%2595%2588%25E6%259B%25B4%25E5%2580%25BC%25E5%25BE%2597%25E8%25AE%25A9%25E4%25BA%25BA%25E7%2595%2599%25E5%25BF%2583/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%2585%25AD%25E5%25B0%2581%25E4%25BF%25A1-%25E5%2589%25AF%25E4%25BD%259C%25E7%2594%25A8%25E6%25AF%2594%25E8%258D%25AF%25E6%2595%2588%25E6%259B%25B4%25E5%2580%25BC%25E5%25BE%2597%25E8%25AE%25A9%25E4%25BA%25BA%25E7%2595%2599%25E5%25BF%2583/6.png" alt=""></a></p><ul><li>左：Henri Cartier-Bresson；右：Mai</li></ul><p>最后，ISO：</p><p>我们知道，如果光圈和快门不变，ISO 越高，感光元件的感光能力就越强，照片也就会越亮，反之亦然。</p><p>但我们现在还应该知道，ISO 越高，画面的纯净度就越低，就越容易出现噪点这个东西（白噪点其实还好，关键是现在数码相机的彩色噪点太要命了），而 ISO 越低，画面的纯净度就越高，就越容易拍出一些更细腻的画面。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%2585%25AD%25E5%25B0%2581%25E4%25BF%25A1-%25E5%2589%25AF%25E4%25BD%259C%25E7%2594%25A8%25E6%25AF%2594%25E8%258D%25AF%25E6%2595%2588%25E6%259B%25B4%25E5%2580%25BC%25E5%25BE%2597%25E8%25AE%25A9%25E4%25BA%25BA%25E7%2595%2599%25E5%25BF%2583/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%2585%25AD%25E5%25B0%2581%25E4%25BF%25A1-%25E5%2589%25AF%25E4%25BD%259C%25E7%2594%25A8%25E6%25AF%2594%25E8%258D%25AF%25E6%2595%2588%25E6%259B%25B4%25E5%2580%25BC%25E5%25BE%2597%25E8%25AE%25A9%25E4%25BA%25BA%25E7%2595%2599%25E5%25BF%2583/7.png" alt=""></a></p><p>所以，特定的光圈要的是特定的景深，特定的快门要的是特定的速度，特定的 ISO 要的是尽可能高或尽可能低的画质……你没有看错，很偶尔的时候，我们可能会需要尽可能低的画质。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%2585%25AD%25E5%25B0%2581%25E4%25BF%25A1-%25E5%2589%25AF%25E4%25BD%259C%25E7%2594%25A8%25E6%25AF%2594%25E8%258D%25AF%25E6%2595%2588%25E6%259B%25B4%25E5%2580%25BC%25E5%25BE%2597%25E8%25AE%25A9%25E4%25BA%25BA%25E7%2595%2599%25E5%25BF%2583/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%2585%25AD%25E5%25B0%2581%25E4%25BF%25A1-%25E5%2589%25AF%25E4%25BD%259C%25E7%2594%25A8%25E6%25AF%2594%25E8%258D%25AF%25E6%2595%2588%25E6%259B%25B4%25E5%2580%25BC%25E5%25BE%2597%25E8%25AE%25A9%25E4%25BA%25BA%25E7%2595%2599%25E5%25BF%2583/8.png" alt=""></a></p><p>所以，现在可以说回到上次聊过的这张照片儿了：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%2585%25AD%25E5%25B0%2581%25E4%25BF%25A1-%25E5%2589%25AF%25E4%25BD%259C%25E7%2594%25A8%25E6%25AF%2594%25E8%258D%25AF%25E6%2595%2588%25E6%259B%25B4%25E5%2580%25BC%25E5%25BE%2597%25E8%25AE%25A9%25E4%25BA%25BA%25E7%2595%2599%25E5%25BF%2583/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%2585%25AD%25E5%25B0%2581%25E4%25BF%25A1-%25E5%2589%25AF%25E4%25BD%259C%25E7%2594%25A8%25E6%25AF%2594%25E8%258D%25AF%25E6%2595%2588%25E6%259B%25B4%25E5%2580%25BC%25E5%25BE%2597%25E8%25AE%25A9%25E4%25BA%25BA%25E7%2595%2599%25E5%25BF%2583/9.png" alt=""></a></p><ul><li>这张照片儿的参数是 [1/125s F8 ISO200]</li></ul><p>我可不可以用 [1/30s F16 ISO200]？可以，虽然光圈减小了两档，但快门放慢了两档，所以曝光情况没有变，但“副作用”明显：ISO 没有变化，光圈从 F8 变成了 F16，在这种距离下，景深其实没什么太大变化，都是全景深，但快门从 1/125s 变成了 1/30s。</p><p>我当时在达祖小学里溜达，随时要拍跑来跑去的孩子，1/125s 还基本能应付，但 1/30s 就比较捉急了。</p><p>当然，快门慢下来，也许我能蒙上几张那种看起来特别随性、特别动感、特别有劲儿的照片儿，但当时在那个环境里，我需要的是一组稳定的、有持续性的、可以普遍适用的参数组合。</p><p>那我可不可以用 [1/1000s F2.8 ISO200]？可以，虽然快门加快了三档，但光圈也增大了三档，所以曝光情况没有变，但“副作用”明显：ISO 没有变化，快门从 1/125s 变成了1/1000s，足够快，孩子们变成疯狗我都不怕拍糊了，但光圈从 F8 变成了 F2.8，景深大幅度收紧，孩子们前后跑来跑去的时候我很可能对不上焦，景深太浅，随便一跑就出焦了。</p><p>另外，我个人目前特别不喜欢虚化这个东西，虚化能弱一点是一点，所以，如果条件允许，通常我的光圈调得都是比较小的。</p><p>那我可不可以用 [1/2000s F16 ISO12800]？可以，曝光一致，但“副作用”明显：光圈从 F8变成了 F16，足够的景深，快门从 1/125s 变成了 1/2000s，孩子们坐上火箭我都不怕拍糊了，但 ISO 从 200 变成了 12800，画面纯净度会大打折扣，即便后期修图的时候我再努力，也很难让这张照片儿有这种油油润润的感觉了。</p><p>所以，我认为在这个场景下， [1/125s F8 ISO200] 是最合适的曝光参数组合，次一等的选择是 [1/60s F8 ISO100] 和 [1/125s F11 ISO400]。</p><p>但我上次说过，如果现在我能重拍这张照片儿，我会用 [1/250s F8 ISO400] 这组参数，因为ISO200 和 ISO400 基本没有肉眼可见的画质影响，但提高一档 ISO，我就能加快一档快门，对我来说，在当时那种情况下，这显然是更保险的一种选择。</p><p>好啦，如果现在我直接给你这么一个参数组合，估计你应该会分析为什么是这样而不是那样了。但如果从一开始就要你自己做决定，该怎么样，不该怎么样，你需要从哪儿下手呢？</p><p>咱们之后有时间再继续聊。</p>',41)])])}const h=A(s,[["render",i]]);export{g as __pageData,h as default};
